===== PodcastGuestForm =====
'use client';

import { useState, type FormEvent } from 'react';
import { isValidEmail } from '@/lib/validators';
import { PaperPlaneTilt } from '@/components/icons';

/*
 * "Be a guest on our first season" form. Submits to the existing
 * /api/cms/submissions/volunteer endpoint with role="Podcast guest"
 * so entries land in the admin inbox without a new table.
 */
export default function PodcastGuestForm({ guestEmail = 'guest@teww.org' }: { guestEmail?: string }) {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [pitch, setPitch] = useState('');
  const [status, setStatus] = useState<{ text: string; error: boolean }>({ text: '', error: false });
  const [submitting, setSubmitting] = useState(false);

  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!name.trim()) {
      setStatus({ text: 'Please enter your name.', error: true });
      return;
    }
    if (!isValidEmail(email)) {
      setStatus({ text: 'Please enter a valid email.', error: true });
      return;
    }
    if (pitch.trim().length < 20) {
      setStatus({ text: 'A sentence or two about your story helps — at least 20 characters.', error: true });
      return;
    }
    setSubmitting(true);
    setStatus({ text: 'Sending…', error: false });
    try {
      const r = await fetch('/api/submissions/volunteer', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: name.trim(),
          email: email.trim(),
          role: 'Podcast guest',
          skills: null,
          message: pitch.trim(),
        }),
      });
      if (!r.ok) throw new Error('HTTP ' + r.status);
      setStatus({ text: "Thank you — we'll be in touch before season one airs.", error: false });
      setName(''); setEmail(''); setPitch('');
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      setStatus({ text: `Couldn't send: ${msg}. Email us at ${guestEmail} instead.`, error: true });
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <form className="pod-guest-form" onSubmit={submit} aria-labelledby="pod-guest-heading">
      <div className="pay-field">
        <label htmlFor="pg-name">Your name</label>
        <input id="pg-name" type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Jane Doe" />
      </div>
      <div className="pay-field">
        <label htmlFor="pg-email">Email</label>
        <input id="pg-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" />
      </div>
      <div className="pay-field">
        <label htmlFor="pg-pitch">Your story (1–2 sentences)</label>
        <textarea
          id="pg-pitch"
          rows={4}
          className="vol-textarea"
          value={pitch}
          onChange={(e) => setPitch(e.target.value)}
          placeholder="What would you want to talk about on the show?"
        />
      </div>
      <button
        type="submit"
        className="btn-primary"
        style={{ width: '100%', justifyContent: 'center' }}
        disabled={submitting}
      >
        <PaperPlaneTilt size="1em" aria-hidden="true" />{' '}
        {submitting ? 'Sending…' : 'Send my pitch'}
      </button>
      <p
        aria-live="polite"
        className="vol-status"
        style={{ color: status.error ? 'var(--accent)' : 'var(--fg-muted)' }}
      >
        {status.text || <>Or email <a href={`mailto:${guestEmail}`} className="pod-guest-email">{guestEmail}</a> directly.</>}
      </p>
    </form>
  );
}
===== PhotoTile =====
'use client';

import type { MouseEvent } from 'react';
import { ArrowsOut, ImageSquare } from '@/components/icons';
import { isSafeImageUrl } from '@/lib/utils';

export interface PhotoData {
  id?: string;
  cls?: string;
  cat?: string;
  loc?: string;
  caption?: string;
  grad1?: string;
  grad2?: string;
  img?: string;
}

export interface PhotoTileProps {
  photo?: PhotoData;
}

/*
 * Photo tile that opens the lightbox on click. Uses a native
 * <button> rather than role="button" on a div — the browser handles
 * keyboard focus, Enter/Space activation, and focus-visible styling
 * automatically. Default button chrome is stripped via `all: unset`
 * in globals.css with the photo-tile base styles re-applied.
 */
export default function PhotoTile({ photo }: PhotoTileProps) {
  const {
    cls = 'p-4-2', cat = '', loc = '', caption = '',
    grad1 = '#1f61ff', grad2 = '#1349d4', img = '',
  } = photo || {};

  const gradient = `linear-gradient(135deg, ${grad1} 0%, ${grad2} 100%)`;
  const safeImg = isSafeImageUrl(img) ? img : '';

  function open(e: MouseEvent<HTMLButtonElement>) {
    if (typeof window !== 'undefined' && typeof window.openPhotoLightbox === 'function') {
      window.openPhotoLightbox(e.currentTarget);
    }
  }

  return (
    <button
      type="button"
      className={`photo-tile ${cls}`}
      data-filter-target="photos"
      data-cat={cat}
      style={{ background: gradient }}
      onClick={open}
      aria-label={`${caption} — ${loc}`}
      data-bg={gradient}
      data-caption={caption}
      data-loc={loc}
      data-img={safeImg}
    >
      {safeImg ? (
        <div className="ph-img-bg" style={{ backgroundImage: `url('${safeImg}')` }}></div>
      ) : (
        <div className="ph-placeholder"><ImageSquare size="1em" aria-hidden="true" /></div>
      )}
      <div className="overlay">
        <div className="ph-title">{caption}</div>
        <div className="ph-meta">{loc}</div>
      </div>
      <div className="photo-zoom-hint" aria-hidden="true">
        <ArrowsOut weight="bold" size="1em" aria-hidden="true" />
      </div>
    </button>
  );
}
