===== VideoCard =====
import { Play } from '@/components/icons';

/*
 * Video card. When `youtubeId` is set, renders a lazy-loaded YouTube
 * iframe (nocookie domain) sized to 16:9. Without an ID, shows the
 * legacy gradient placeholder — useful while editors are still
 * pasting IDs from the admin dashboard.
 */
export interface VideoData {
  id?: string;
  bg?: string;
  label?: string;
  dur?: string;
  title?: string;
  desc?: string;
  date?: string;
  views?: string;
  cat?: string;
  youtubeId?: string;
}

export default function VideoCard({ video }: { video?: VideoData }) {
  const {
    bg = 'vid-bg-1', label = '', dur = '', title = '', desc = '',
    date = '', views = '', cat = '', youtubeId = '',
  } = video || {};

  return (
    <div className="video-card" data-filter-target="videos" data-cat={cat}>
      {youtubeId ? (
        <div className="video-embed">
          <iframe
            src={`https://www.youtube-nocookie.com/embed/${youtubeId}?rel=0`}
            title={title}
            loading="lazy"
            referrerPolicy="strict-origin-when-cross-origin"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
            allowFullScreen
          ></iframe>
        </div>
      ) : (
        <div className={`video-thumb ${bg}`}>
          <div className="vid-inner-label">{label || 'Coming soon'}</div>
          <div className="play-btn"><Play weight="fill" size="1em" aria-hidden="true" /></div>
          {dur ? <div className="dur">{dur}</div> : null}
          <div className="video-pending" aria-hidden="true">Awaiting YouTube link</div>
        </div>
      )}
      <div className="video-body">
        <h4>{title}</h4>
        {desc ? <p>{desc}</p> : null}
        {(date || views) ? (
          <div className="video-meta">
            {date ? <span>{date}</span> : null}
            {date && views ? <span className="sep">·</span> : null}
            {views ? <span>{views}</span> : null}
          </div>
        ) : null}
      </div>
    </div>
  );
}
===== FilterablePhotoGrid =====
'use client';

import { useState } from 'react';
import PhotoTile, { type PhotoData } from '@/components/media/PhotoTile';

interface FilterablePhotoGridProps {
  photos: PhotoData[];
  cats: string[];
}

export default function FilterablePhotoGrid({ photos, cats }: FilterablePhotoGridProps) {
  const [filter, setFilter] = useState('all');
  const visible = filter === 'all' ? photos : photos.filter((p: PhotoData) => p.cat === filter);

  return (
    <>
      {cats.length > 0 ? (
        <div className="filter-bar" data-filter-group="photos">
          <div className="filter-label">Filter</div>
          <button
            type="button"
            className={`filter-pill${filter === 'all' ? ' active' : ''}`}
            aria-pressed={filter === 'all'}
            onClick={() => setFilter('all')}
          >
            All
          </button>
          {cats.map((c: string) => (
            <button
              key={c}
              type="button"
              className={`filter-pill${filter === c ? ' active' : ''}`}
              aria-pressed={filter === c}
              onClick={() => setFilter(c)}
            >
              {c.charAt(0).toUpperCase() + c.slice(1)}
            </button>
          ))}
        </div>
      ) : null}

      <div className="photo-grid">
        {visible.length > 0 ? (
          visible.map((p: PhotoData) => <PhotoTile key={p.id || p.caption} photo={p} />)
        ) : (
          <p style={{ gridColumn: '1 / -1', color: 'var(--fg-muted)' }}>
            {photos.length === 0 ? 'No photos yet.' : 'No photos match this filter.'}
          </p>
        )}
      </div>
    </>
  );
}
