/*
 * Video card. When `youtubeId` is set, renders a lazy-loaded YouTube
 * iframe (nocookie domain) sized to 16:9. Without an ID, shows a quiet
 * gold-dashed pending frame — useful while editors are still pasting
 * IDs from the admin dashboard.
 */
export interface VideoData {
  id?: string;
  bg?: string;
  label?: string;
  dur?: string;
  title?: string;
  desc?: string;
  date?: string;
  views?: string;
  cat?: string;
  youtubeId?: string;
}

export default function VideoCard({ video }: { video?: VideoData }) {
  const {
    bg = 'vid-bg-1', label = '', dur = '', title = '', desc = '',
    date = '', views = '', cat = '', youtubeId = '',
  } = video || {};

  return (
    <div className="video-card" data-filter-target="videos" data-cat={cat}>
      {youtubeId ? (
        <div className="video-embed">
          <iframe
            src={`https://www.youtube-nocookie.com/embed/${youtubeId}?rel=0`}
            title={title}
            loading="lazy"
            referrerPolicy="strict-origin-when-cross-origin"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
            allowFullScreen
          ></iframe>
        </div>
      ) : (
        <div className={`video-thumb ${bg}`}>
          {label ? <div className="vid-inner-label">{label}</div> : null}
          {dur ? <div className="dur">{dur}</div> : null}
          <div className="video-pending">Awaiting YouTube link</div>
        </div>
      )}
      <div className="video-body">
        {cat ? <div className="video-chip">{cat}</div> : null}
        <h4>{title}</h4>
        {desc ? <p>{desc}</p> : null}
        {(date || views) ? (
          <div className="video-meta">
            {date ? <span>{date}</span> : null}
            {date && views ? <span className="sep">·</span> : null}
            {views ? <span>{views}</span> : null}
          </div>
        ) : null}
      </div>
    </div>
  );
}

/* ── MEDIA — Sight Beyond Sight ─────────────────────
   Night surfaces, gold hairlines, Literata numerals.
   Grid span classes (.p-*) and the lightbox DOM/JS contract
   (lib/client-init.ts) are load-bearing — restyled, not renamed. */

/* Tab header — eyebrow + Literata title, oversized numeral count */
.media-tab-head {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 24px; margin-bottom: 36px; padding-bottom: 20px;
  border-bottom: 1px solid var(--border);
}
.media-tab-head .section-eyebrow { margin-bottom: 8px; }
.media-tab-title {
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 2.4vw, 2.3rem);
  font-weight: 600; letter-spacing: -.015em; line-height: 1.1;
  color: var(--fg);
}
.media-tab-count {
  display: flex; align-items: baseline; gap: 10px; white-space: nowrap;
  font-family: var(--font-body); font-size: .72rem; font-weight: 700;
  letter-spacing: .14em; text-transform: uppercase; color: var(--fg-muted);
}
.media-tab-count-num {
  font-family: var(--font-display); font-size: 2.4rem; font-weight: 600;
  line-height: 1; letter-spacing: -.02em; color: var(--brand);
  font-variant-numeric: tabular-nums;
}

/* ── PHOTOS — dignified empty state ── */
.photos-empty { position: relative; max-width: 720px; }
.photos-empty-title { margin-bottom: 22px; }
.photos-empty-title em { color: var(--brand); font-style: italic; }
.photos-empty p {
  color: var(--fg-muted); line-height: 1.7; font-size: 1.05rem;
  max-width: 62ch; margin-bottom: 16px;
}
.photos-empty p a { text-decoration: underline; }
.photos-empty-cta {
  margin-top: 28px; padding-top: 28px;
  border-top: 1px solid var(--border);
}

/* Braille dots spelling T-E-W-W (⠞⠑⠺⠺) — one decorative motif.
   A single 5px dot casts the other 13 as box-shadows (14px pitch,
   42px letter advance). aria-hidden in markup. */
.photos-empty-braille {
  position: absolute; top: 8px; right: 0;
  width: 146px; height: 34px;
  pointer-events: none; opacity: .55;
}
.photos-empty-braille span {
  display: block; width: 5px; height: 5px; border-radius: 50%;
  background: transparent; color: var(--brand);
  box-shadow:
    /* T ⠞ dots 2,3,4,5 */ 0 14px, 0 28px, 14px 0, 14px 14px,
    /* E ⠑ dots 1,5    */ 42px 0, 56px 14px,
    /* W ⠺ dots 2,4,5,6 */ 84px 14px, 98px 0, 98px 14px, 98px 28px,
    /* W ⠺              */ 126px 14px, 140px 0, 140px 14px, 140px 28px;
}
@media (max-width: 720px) { .photos-empty-braille { display: none; } }

/* ── PHOTO GRID (when the archive has photos) ── */
.photo-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 16px; grid-auto-rows: 180px; }
.photo-tile {
  border-radius: var(--radius-lg); overflow: hidden; position: relative;
  cursor: pointer; background: var(--bg-subtle);
  border: 1px solid var(--border);
  transition: border-color .2s ease;
}
/* Strip default <button> chrome when .photo-tile is rendered as a
   button (since the FRONTEND_FIXES a11y migration). Browser handles
   Enter/Space activation and focus-visible automatically. */
button.photo-tile {
  font: inherit; color: inherit; text-align: left;
  padding: 0; margin: 0; appearance: none;
  width: 100%; display: block;
}
button.photo-tile:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 3px;
}
.photo-tile:hover { border-color: var(--border-strong); }
/* Caption scrim — literal night ink: it sits on a photograph, not a
   theme surface, so it stays dark in every theme. */
.photo-tile .overlay {
  position: absolute; inset: 0; padding: 18px;
  display: flex; flex-direction: column; justify-content: flex-end;
  background: linear-gradient(180deg, transparent 40%, rgba(16,14,23,.88) 100%);
  color: #f4efe6; opacity: 0; transition: opacity .2s;
}
.photo-tile:hover .overlay,
.photo-tile:focus-visible .overlay { opacity: 1; }
.photo-tile .ph-title { font-family: var(--font-display); font-size: .95rem; font-weight: 600; letter-spacing: -.01em; }
.photo-tile .ph-meta { font-family: var(--font-body); font-size: .72rem; opacity: .8; margin-top: 3px; letter-spacing: .08em; text-transform: uppercase; }
.photo-tile .ph-img-bg { position: absolute; inset: 0; background-size: cover; background-position: center; }
.photo-tile .ph-placeholder { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-family: var(--font-display); font-weight: 700; font-size: 2rem; color: var(--fg-subtle); opacity: .3; }

/* Described badge — the accessibility promise, on every frame.
   Over-photo chip: fixed dark scrim + gold, theme-independent. */
.photo-tile .ph-described {
  position: absolute; top: 12px; left: 12px; z-index: 2;
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 10px; border-radius: var(--radius-full);
  background: rgba(16,14,23,.75);
  border: 1px solid rgba(232,163,61,.4);
  color: #f2b856;
  font-family: var(--font-body); font-size: .6rem; font-weight: 700;
  letter-spacing: .14em; text-transform: uppercase;
  backdrop-filter: blur(4px);
}
.photo-tile .ph-described::before {
  content: ''; width: 5px; height: 5px; border-radius: 50%;
  background: #e8a33d;
}
[data-theme="high-contrast"] .photo-tile .ph-described {
  background: #000; border-color: #fff; color: #fff; backdrop-filter: none;
}

.p-6-4 { grid-column: span 6; grid-row: span 2; }
.p-4-2 { grid-column: span 4; grid-row: span 1; }
.p-4-4 { grid-column: span 4; grid-row: span 2; }
.p-3-2 { grid-column: span 3; grid-row: span 1; }
.p-6-2 { grid-column: span 6; grid-row: span 1; }
.p-8-2 { grid-column: span 8; grid-row: span 1; }

/* ── LIGHTBOX overrides ──
   Base lightbox CSS is injected by lib/client-init.ts at runtime and
   wins on cascade order, so these use the #photoLightbox id for
   specificity. The lightbox is a dark room over a photograph in every
   theme — literal night/gold values are intentional here. */
#photoLightbox { background: rgba(11,10,16,.95); }
#photoLightbox .lb-image {
  border: 1px solid rgba(232,163,61,.3);
  border-radius: var(--radius-lg);
  background: #171420;
}
#photoLightbox .lb-loc { color: #f2b856; }
#photoLightbox .lb-described {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 10px; border-radius: var(--radius-full);
  border: 1px solid rgba(232,163,61,.4); color: #f2b856;
  font-size: .64rem; letter-spacing: .14em;
}
#photoLightbox .lb-described::before {
  content: ''; width: 5px; height: 5px; border-radius: 50%; background: #e8a33d;
}
#photoLightbox .lb-close:focus-visible,
#photoLightbox .lb-nav:focus-visible {
  outline: 3px solid #f2b856; outline-offset: 2px;
}

/* ── PODCAST EPISODE ROWS (when the show is live) ── */
.pod-list { display: flex; flex-direction: column; gap: 16px; }
.pod-row {
  display: flex; gap: 20px; align-items: center;
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  transition: border-color .2s, transform .2s;
}
.pod-row:hover { border-color: var(--border-strong); transform: translateY(-2px); }
/* Episode art — Literata numeral on a quiet night tile. The v2–v5
   variant classes come from CMS data; each keeps a distinct look. */
.pod-art {
  width: 88px; height: 88px; border-radius: var(--radius-md); flex-shrink: 0;
  background: var(--bg-subtle); border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  color: var(--brand);
  font-family: var(--font-display); font-weight: 600; font-size: 1.7rem;
  letter-spacing: -.02em; font-variant-numeric: tabular-nums;
  position: relative; overflow: hidden;
}
.pod-art.v2 { color: var(--accent); }
.pod-art.v3 { background: var(--brand-subtle); border-color: color-mix(in oklab, var(--brand) 40%, var(--border)); }
.pod-art.v4 { background: var(--accent-subtle); color: var(--accent); }
.pod-art.v5 { border-color: color-mix(in oklab, var(--accent) 40%, var(--border)); color: var(--accent); }
.pod-body { flex: 1; }
.pod-body .ep { font-family: var(--font-body); font-size: .68rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--brand); margin-bottom: 4px; }
.pod-body h4 { font-family: var(--font-display); font-size: 1.1rem; font-weight: 600; color: var(--fg); margin-bottom: 4px; letter-spacing: -.01em; }
.pod-body p { font-size: .88rem; color: var(--fg-muted); line-height: 1.5; margin-bottom: 8px; }
.pod-meta { display: flex; gap: 14px; font-size: .78rem; color: var(--fg-subtle); font-family: var(--font-body); }
.pod-meta span { display: inline-flex; align-items: center; gap: 4px; }
.pod-play {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--brand); color: var(--brand-fg);
  border: none; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; flex-shrink: 0;
  transition: background .15s, transform .1s;
}
.pod-play:hover { background: var(--brand-hover); }
.pod-play:active { transform: scale(.93); }

/* ── VIDEO CARDS ── */
.video-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.video-card {
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: border-color .2s, transform .2s;
}
.video-card:hover { border-color: var(--border-strong); transform: translateY(-2px); }
.video-thumb {
  aspect-ratio: 16/9; position: relative;
  background: var(--bg-subtle);
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.video-thumb .dur {
  position: absolute; bottom: 12px; right: 12px; z-index: 2;
  background: var(--bg-elevated); border: 1px solid var(--border);
  color: var(--fg); font-family: var(--font-body);
  font-size: .7rem; font-weight: 700;
  padding: 3px 8px; border-radius: var(--radius-sm);
  font-variant-numeric: tabular-nums;
}
/* CMS `label` field ("FEATURE", "TALK", …) as a quiet chip */
.vid-inner-label {
  position: absolute; top: 12px; left: 12px; z-index: 2;
  background: var(--bg-elevated); border: 1px solid var(--border);
  color: var(--fg-muted);
  font-family: var(--font-body); font-size: .62rem; font-weight: 700;
  letter-spacing: .14em; text-transform: uppercase;
  padding: 4px 10px; border-radius: var(--radius-full);
}
/* CMS `bg` variant classes — night duotones drawn from the tokens,
   readable in all three themes (old blue/orange gradients retired). */
.vid-bg-1 { background: color-mix(in oklab, var(--brand) 10%, var(--bg-subtle)); }
.vid-bg-2 { background: color-mix(in oklab, var(--accent) 10%, var(--bg-subtle)); }
.vid-bg-3 { background: var(--bg-subtle); }
.vid-bg-4 { background: color-mix(in oklab, var(--brand) 6%, var(--bg-subtle)); }
.vid-bg-5 { background: color-mix(in oklab, var(--accent) 6%, var(--bg-subtle)); }
.vid-bg-6 { background: color-mix(in oklab, var(--fg) 5%, var(--bg-subtle)); }

.video-body { padding: 18px 20px 22px; }
.video-chip {
  display: inline-flex; align-items: center;
  background: var(--brand-subtle); color: var(--brand);
  font-family: var(--font-body); font-size: .64rem; font-weight: 700;
  letter-spacing: .12em; text-transform: uppercase;
  padding: 3px 10px; border-radius: var(--radius-full);
  margin-bottom: 10px;
}
.video-body h4 { font-family: var(--font-display); font-size: 1.05rem; font-weight: 600; color: var(--fg); margin-bottom: 6px; letter-spacing: -.01em; line-height: 1.25; }
.video-body p { font-size: .85rem; color: var(--fg-muted); line-height: 1.5; margin-bottom: 10px; }
.video-meta { font-size: .75rem; color: var(--fg-subtle); font-family: var(--font-body); display: flex; gap: 10px; align-items: center; }
.video-meta .sep { opacity: .5; }

/* Media extras — accessibility-promise band, podcast featured art,
   media-scoped filter-pill tap targets. Loads after 08-footer-prose
   so the pill overrides below win on cascade order. */

/* ── Accessibility promise — gold-hairline feature row ── */
.media-promise-section { padding-top: 0; }
.media-promise {
  border-top: 1px solid var(--brand);
  border-bottom: 1px solid var(--brand);
  padding: clamp(32px, 5vw, 56px) 0;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  gap: clamp(24px, 4vw, 64px);
  align-items: center;
}
.photo-accessibility-eyebrow { margin-bottom: 10px; }
.photo-accessibility-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 2.6vw, 2.4rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.15;
  color: var(--fg);
  margin: 0;
  text-wrap: balance;
}
.photo-accessibility-title em { color: var(--brand); font-style: italic; }
.photo-accessibility-body {
  color: var(--fg-muted);
  line-height: 1.7;
  font-size: 1.02rem;
  max-width: 52ch;
  margin: 0;
}
@media (max-width: 780px) {
  .media-promise { grid-template-columns: 1fr; gap: 18px; }
}

/* ── Podcast featured (live-show state) ── */
.pod-featured-eyebrow {
  font-family: var(--font-body);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 12px;
}
.pod-featured-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 2.6vw, 2.2rem);
  font-weight: 600;
  color: var(--fg);
  margin-bottom: 12px;
  letter-spacing: -.015em;
  line-height: 1.15;
}
.pod-featured-desc { color: var(--fg-muted); margin-bottom: 20px; line-height: 1.65; }
/* Show art — night tile with echo-ripple rings (sound made visible) */
.pod-art-bg {
  aspect-ratio: 1;
  border-radius: var(--radius-lg);
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.pod-art-bg::before {
  content: '';
  position: absolute; inset: 0;
  background: repeating-radial-gradient(
    circle at 50% 50%,
    transparent 0 34px,
    color-mix(in oklab, var(--brand) 30%, transparent) 34px 35px
  );
  opacity: .55;
  pointer-events: none;
}
[data-theme="high-contrast"] .pod-art-bg::before { opacity: .35; }
.pod-art-inner {
  color: var(--fg);
  text-align: center;
  z-index: 1;
  font-family: var(--font-display);
  padding: 0 20px;
}
.pod-art-name {
  font-size: 2.2rem;
  font-weight: 600;
  letter-spacing: -.02em;
  line-height: 1.05;
}
.pod-art-meta {
  font-family: var(--font-body);
  font-size: .68rem;
  font-weight: 700;
  margin-top: 14px;
  letter-spacing: .14em;
  color: var(--brand);
}
.pod-list-heading {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -.01em;
  color: var(--fg);
  margin-bottom: 18px;
}

/* ── Filter pills (media grids only) — ≥44px tap targets.
   Scoped to the media data-filter-groups so the shared .filter-pill
   base (08-footer-prose.css, also used on /documents) is untouched. */
[data-filter-group="photos"] .filter-pill,
[data-filter-group="videos"] .filter-pill {
  min-height: 44px;
  padding: 9px 18px;
}

/* Media — video embed (16:9 iframe), pending placeholder,
   podcast coming-soon editorial + guest form. */

/* 16:9 YouTube embed — unchanged frame contract */
.video-embed {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  background: #000;
  overflow: hidden;
}
.video-embed iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
}

/* Pending state — quiet gold-dashed frame inside the 16:9 thumb */
.video-thumb::after {
  content: '';
  position: absolute; inset: 10px;
  border: 1px dashed color-mix(in oklab, var(--brand) 55%, transparent);
  border-radius: calc(var(--radius-lg) - 6px);
  pointer-events: none;
}
[data-theme="high-contrast"] .video-thumb::after { border-color: var(--brand); }
.video-card .video-pending {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: var(--font-body);
  font-size: .66rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--brand);
  padding: 0 12px;
  text-align: center;
}
.video-card .video-pending::before,
.video-card .video-pending::after {
  content: '';
  width: 20px; height: 1px;
  background: var(--brand);
  flex-shrink: 0;
}

/* ── Podcast "coming soon" — night editorial, two columns ── */
.pod-coming-soon {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr);
  gap: clamp(28px, 5vw, 72px);
  align-items: start;
}
.pod-coming-soon-intro { padding-top: 8px; }
.pod-coming-soon-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  font-family: var(--font-body);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 22px;
}
.pod-coming-soon-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--brand);
  box-shadow: 0 0 0 0 color-mix(in oklab, var(--brand) 45%, transparent);
  animation: pod-pulse 1.8s infinite;
}
@keyframes pod-pulse {
  0%   { box-shadow: 0 0 0 0   color-mix(in oklab, var(--brand) 45%, transparent); }
  70%  { box-shadow: 0 0 0 9px color-mix(in oklab, var(--brand) 0%,  transparent); }
  100% { box-shadow: 0 0 0 0   color-mix(in oklab, var(--brand) 0%,  transparent); }
}
@media (prefers-reduced-motion: reduce) {
  .pod-coming-soon-dot { animation: none; }
}
.pod-coming-soon-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.6vw, 3rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.08;
  color: var(--fg);
  margin: 0 0 6px;
  text-wrap: balance;
}
/* Gold waveform — vertical bars shaped by an elliptical mask.
   Decorative (aria-hidden in markup). */
.pod-wave {
  height: 44px;
  max-width: 340px;
  margin: 20px 0 22px;
  background: repeating-linear-gradient(90deg, var(--brand) 0 3px, transparent 3px 10px);
  -webkit-mask-image: radial-gradient(70% 100% at 50% 50%, #000 30%, rgba(0,0,0,.35) 60%, transparent 78%);
          mask-image: radial-gradient(70% 100% at 50% 50%, #000 30%, rgba(0,0,0,.35) 60%, transparent 78%);
  opacity: .8;
}
.pod-coming-soon-desc {
  color: var(--fg-muted);
  line-height: 1.7;
  font-size: 1.05rem;
  margin: 0;
  max-width: 46ch;
}

/* Guest pitch form — elevated night card, gold hairline top */
.pod-coming-soon-form {
  padding: clamp(24px, 3vw, 32px);
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-top: 2px solid var(--brand);
  border-radius: var(--radius-lg);
}
.pod-coming-soon-form-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -.01em;
  color: var(--fg);
  margin: 0 0 8px;
}
.pod-coming-soon-form-desc {
  font-size: .92rem;
  color: var(--fg-muted);
  line-height: 1.6;
  margin: 0 0 20px;
}
.pod-guest-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
/* Night inputs — override the shared .pay-field blue-era focus ring
   (03-page-hero-donate.css) inside this form only. */
.pod-guest-form .pay-field input,
.pod-guest-form .vol-textarea {
  background: var(--bg);
  min-height: 48px;
}
.pod-guest-form .pay-field input:focus,
.pod-guest-form .vol-textarea:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 3px var(--brand-subtle);
}
.pod-guest-email {
  color: var(--brand);
  text-decoration: underline;
}
.pod-guest-email:hover { color: var(--brand-hover); }

@media (max-width: 780px) {
  .pod-coming-soon {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}
